import {Text, View} from 'react-native';
import InitialAvatar from './InitialAvatar';
import {Color} from '../../../../constants';
import styles from '../styles';
import {WorkSpace} from '../../../../model/interface/home.interface';
import TextCM from '../../../components/Text';
import {ProgressBar} from '@ui-kitten/components';

type CardProps = {
  data: WorkSpace;
  backgroundColor?: keyof typeof Color;
};
const Card = ({data, backgroundColor}: CardProps) => {
  const progress = data.totalTask
    ? data.totalTaskCompleted / data.totalTask
    : 0;

  return (
    <View
      style={[
        styles.cardContainer,
        {backgroundColor: Color[backgroundColor || 'pending']},
      ]}>
      <View style={styles.cardFirst}>
        <InitialAvatar text={data.name} />
        <View style={styles.textFirst}>
          <TextCM style={styles.textBold} numberOfLines={1}>
            {data.name}
          </TextCM>
          <TextCM style={styles.colorText} numberOfLines={2}>
            {data.description}
          </TextCM>
        </View>
      </View>
      <View style={{padding: 10}}>
        <TextCM style={styles.textCenter}>Tiến độ thực hiện</TextCM>
        <View style={styles.progressRow}>
          <ProgressBar
            progress={progress}
            status='control'
            style={{flex: 1}}
          />

          <Text style={styles.progressText}>
            {(progress * 100).toFixed(2)}%
          </Text>
          <Text style={styles.progressCount}>
            ({data.totalTaskCompleted}/{data.totalTask})
          </Text>
        </View>
      </View>
      <View style={styles.creatorSection}>
        <View style={styles.avatar}>
          <Text style={styles.avatarText}>
            {data.owner.charAt(0).toUpperCase()}
          </Text>
        </View>
        <Text style={styles.creatorText}>Tạo bởi {data.owner}</Text>
      </View>
    </View>
  );
};

export default Card;
