import useBoardStore from '../../../../../board/store';
import {Icon, List, ListItem} from '@ui-kitten/components';
import {GroupTaskList} from '../../../../../board/store/interface';
import {useTranslation} from 'react-i18next';
type Props = {
  onSave: (data: any) => void;
  value: any;
};

const ModalStatus = ({onSave, value}: Props) => {
  const {t} = useTranslation();
  const {groupTaskList} = useBoardStore();

  const handleSelect = (item: GroupTaskList) => {
    onSave({
      status: item.id,
    });
  };
  return (
    <List
      data={groupTaskList?.sort((a: GroupTaskList, b: GroupTaskList) => {
        const orderA = JSON.parse(a.attr).order;
        const orderB = JSON.parse(b.attr).order;
        return orderA - orderB;
      })}
      renderItem={({item}) => (
        <ListItem
          onPress={() => handleSelect(item)}
          accessoryRight={
            value !== null && value === item.id ? (
              <Icon name="checkmark-outline" width={24} height={24} />
            ) : undefined
          }
          title={
            item.type === 'custom' ? item.name : t('board.status-' + item.type)
          }
        />
      )}
    />
  );
};

export default ModalStatus;
