import { WorkSpace } from '../model/interface/home.interface';
import {getConfig} from './httpClient';

export const createHomeServices = (fetchRequest: any) => ({
    async getWorkPlace() {
    try {
      const endpoint = '/services/etask/api/work-space/search?page=0&size=5&sort=lastAccessDate,desc';
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
         body: JSON.stringify({})
      });
      return Promise.resolve({
        data: data?.data as WorkSpace[],
      });
    } catch (error) {
      console.error(error);
      return Promise.reject(error);
    }
  },
  async getOwnWorkPlace() {
    try {
      const endpoint = '/services/etask/api/work-space/search?type=owner&page=0&size=5&sort=createdDate,desc';
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
         body: JSON.stringify({})
      });
       console.log('📦 Data trả về từ fetchRequest:', data);
      return Promise.resolve({
        data: data?.data as WorkSpace[],
      });
    } catch (error) {
      console.error(error);
      return Promise.reject(error);
    }
  },
   async getAuthorWorkPlace() {
    try {
      const endpoint = '/services/etask/api/work-space/search?type=authorized&page=0&size=5';
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
         body: JSON.stringify({})
      });
      return Promise.resolve({
        data: data?.data as WorkSpace[],
      });
    } catch (error) {
      console.error(error);
      return Promise.reject(error);
    }
  },
})