import {
  Calendar,
  CheckBox,
  Divider,
  Icon,
  IndexPath,
  Input,
} from '@ui-kitten/components';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Pressable, View} from 'react-native';
import TextCM from '../../../../../../components/Text';
import {useEffect, useState} from 'react';
import {DateUtils} from '../../../../../../../utils';
import styles from './styles';
import {ConfigRemind} from '../../../task-detail-item/helper';
import DropdownListCM from '../../../../../../components/DropDownList';
import {listRepeatType, listTimeRepeat, RepeatType} from './helper';
import {Color} from '../../../../../../../constants';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import ModalDate from '../modal-date';

type Props = {
  onClose: () => void;
  onSave?: (data: any) => void;
  valueConfig?: ConfigRemind;
};

const ModalRemind = ({onClose, onSave, valueConfig}: Props) => {
  const [dataForm, setDataForm] = useState<ConfigRemind>({
    ...valueConfig,
  } as ConfigRemind);
  const [selectTimeRepeat, setSelectTimeRepeat] = useState<IndexPath>(
    listTimeRepeat?.find(t => t.value === dataForm?.typeLoop)
      ? (new IndexPath(
          listTimeRepeat?.findIndex(t => t.value === dataForm?.typeLoop),
        ) as any)
      : null,
  );

  const [selectRepeatType, setSelectRepeatType] = useState<IndexPath>(
    valueConfig?.iterationCount ? new IndexPath(1) : new IndexPath(0),
  );

  const [showCheckbox, setShowCheckbox] = useState(false);
  const [showModalDate, setShowModalDate] = useState<'dateStart' | 'dateEnd'>();

  useEffect(() => {
    if (selectTimeRepeat) {
      setShowCheckbox(true);
    } else {
      setShowCheckbox(false);
    }
    const dataSelect = listTimeRepeat?.[selectTimeRepeat?.row as number]?.value;
    setDataForm({
      ...dataForm,
      typeLoop: dataSelect,
      alwaysLoop: dataSelect ? true : false,
    });
  }, [selectTimeRepeat]);
  const handleSave = (data: any) => {
    setDataForm({
      ...dataForm,
      ...data,
      iterationCount: data.hasOwnProperty('dateEnd')
        ? null
        : dataForm.iterationCount,
    });
    setShowModalDate(undefined);
  };

  const onChangeCheckBox = (value: boolean) => {
    setDataForm({
      ...dataForm,
      alwaysLoop: value,
      dateEnd: value ? null : dataForm.dateEnd,
      iterationCount: value ? null : dataForm.iterationCount,
    });
  };

  const handleSaveSelect = (value: any, type: string) => {
    setDataForm({
      ...dataForm,
      [type]: value,
      dateEnd: null,
    });
  };

  const dataSubmit = () => {
    onSave?.(dataForm);
    onClose();
  };

  return (
    <>
      <HeaderCM
        onPressIconLeft={onClose}
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        title={'Remind'}
        renderContentRight={() => (
          <Pressable onPress={dataSubmit}>
            <TextCM>Done</TextCM>
          </Pressable>
        )}
      />
      <Divider />

      <View style={{paddingHorizontal: 16, paddingVertical: 10, rowGap: 16}}>
        <TextCM style={styles.textTitle}>Thời gian nhắc nhở</TextCM>
        <Pressable
          onPress={() => setShowModalDate('dateStart')}
          style={{
            borderWidth: 1,
            borderColor: Color.borderColor,
            height: 40,
            paddingHorizontal: 16,
            borderRadius: 8,
            alignItems: 'flex-start',
            justifyContent: 'center',
          }}>
          <TextCM>
            {dataForm?.dateStart
              ? DateUtils.convertDateToDDMMYYYY_H_M(dataForm?.dateStart)
              : 'Chọn thời gian'}
          </TextCM>
        </Pressable>
        <DropdownListCM
          label="Lặp lại"
          placeholder="Chọn loại thời gian lặp lại"
          listData={listTimeRepeat}
          onSelect={setSelectTimeRepeat}
          valueSelect={selectTimeRepeat}
          size="medium"
        />
        {showCheckbox && (
          <CheckBox
            onChange={value => onChangeCheckBox(value)}
            checked={dataForm?.alwaysLoop}
            children={<TextCM>Lặp lại vĩnh viễn</TextCM>}
          />
        )}

        {showCheckbox && !dataForm?.alwaysLoop && (
          <View
            style={{
              rowGap: 10,
            }}>
            <DropdownListCM
              listData={listRepeatType}
              onSelect={setSelectRepeatType}
              valueSelect={selectRepeatType}
              size="medium"
            />
            {selectRepeatType?.row === RepeatType.repeat && (
              <Input
                placeholder="Nhập số lần"
                keyboardType="numeric"
                value={dataForm?.iterationCount}
                onChangeText={value =>
                  handleSaveSelect(value, 'iterationCount')
                }
              />
            )}
            {selectRepeatType?.row === RepeatType.end && (
              <Pressable
                onPress={() => setShowModalDate('dateEnd')}
                style={{
                  borderWidth: 1,
                  borderColor: Color.borderColor,
                  height: 40,
                  paddingHorizontal: 16,
                  borderRadius: 8,
                  alignItems: 'flex-start',
                  justifyContent: 'center',
                }}>
                <TextCM>
                  {dataForm?.dateEnd
                    ? DateUtils.convertDateToDDMMYYYY_H_M(dataForm?.dateEnd)
                    : 'Chọn thời gian'}
                </TextCM>
              </Pressable>
            )}
          </View>
        )}
      </View>

      <ModalFullScreen
        isVisible={showModalDate === 'dateStart'}
        children={
          <ModalDate
            onClose={() => setShowModalDate(undefined)}
            type={'dateStart'}
            value={dataForm?.dateStart}
            option="remind"
            onSave={handleSave}
          />
        }
      />
      <ModalFullScreen
        isVisible={showModalDate === 'dateEnd'}
        children={
          <ModalDate
            onClose={() => setShowModalDate(undefined)}
            type={'dateEnd'}
            value={dataForm?.dateEnd}
            option="remind"
            onSave={handleSave}
          />
        }
      />
    </>
  );
};

export default ModalRemind;
