import {useEffect, useState} from 'react';
import {Color, Font, NavigationName, String} from '../../../constants';
import HeaderCM from '../../components/Header/HeaderCM';
import TableCM from '../../components/Table';
import {
  useBoardService,
  useTaskService,
  useUserService,
} from '../../../hooks/apiHooks/useAPI';
import {useNavigation, useRoute} from '@react-navigation/native';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import TextCM from '../../components/Text';
import {Image, ScrollView, TouchableOpacity, View} from 'react-native';
import PagingCM from '../../components/Paging';
import {Icon} from '@ui-kitten/components';
import {SafeAreaView} from 'react-native-safe-area-context';
import ModalConfirmCM from '../../components/ModalConfirm';
import ModalFullScreen from '../../components/ModalFullScreen';
import AuthorityAndShareScreen from '../../components/Authority';
import {ITask} from '../board/store/interface';
import useBoardStore from '../board/store';
import {KEY_TASK} from '../board/helper';
import {useAppSelector} from '../../../hooks/useRedux';
import {styles} from './styles';

const MyTemplateTask = () => {
  const {t} = useTranslation();
  const BoardServices = useBoardService();
  const Taskservices = useTaskService();
  const UserService = useUserService();
  const navigation = useNavigation<any>();
  const {dataAccount} = useAppSelector(state => state.account);
  const {keyTaskSelect} = useBoardStore();
  const router = useRoute<any>();
  const {listTaskId, listTaskName} = router?.params;
  const [dataTable, setDataTable] = useState<any[]>([]);
  const [totalItems, setTotalItems] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [modalDelete, setModalDelete] = useState(false);
  const [modalCopy, setModalCopy] = useState(false);
  const [currentTask, setCurrentTask] = useState<ITask>();
  const [shareAuthorize, setShareAuthorize] = useState(false);
  const pageSize = 10;
  const setUpDatatableFromApiData = (data: {data: any[]; page: any}) => {
    const dataTable = (
      data.data as (ITask & {
        [key: string]: any;
      })[]
    ).map((item, index) => {
      item.STT = (currentPage - 1) * pageSize + index + 1;
      if (item?.tags?.length) {
        item['board.table-tags'] = (
          <View style={styles.tagsTable}>
            <View style={styles.wrapTxtTag}>
              <TextCM style={styles.txtTag}>{item.tags?.[0]}</TextCM>
            </View>
            {item?.tags?.length > 1 ? (
              <TextCM>+{item?.tags?.length - 1}</TextCM>
            ) : null}
          </View>
        );
      }
      item['board.table-createdDate'] = item.createdDate;
      item['board.table-createdBy'] = (
        <View style={styles.container}>
          <View style={styles.avatarContainer}>
            <Image
              width={32}
              height={32}
              borderRadius={25}
              source={{
                uri: item.avatar || String.DEFAULT_IMAGE,
              }}
            />
          </View>
          <TextCM style={styles.email}>{item.createdBy}</TextCM>
        </View>
      );
      item['board.table-process'] = item.process;
      item['board.table-numberSubtasks'] = item.numberSubtasks;
      item['board.table-action'] = (
        <View
          style={{
            flexDirection: 'row',
            justifyContent: 'space-between',
            gap: 15,
          }}>
          <TouchableOpacity
            onPress={() => {
              navigation.navigate(NavigationName.TaskDetailScreen, {
                taskId: item.id,
                isFromTemplate: true,
              });
            }}>
            <Icon name="edit-2" width={16} height={16} />
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => {
              setModalCopy(true);
              setCurrentTask(item);
            }}>
            <Icon name="copy" width={16} height={16} />
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => {
              setCurrentTask(item);
              setModalDelete(true);
            }}>
            <Icon name="trash-2" width={16} height={16} />
          </TouchableOpacity>
          {keyTaskSelect == KEY_TASK['template-task'] && (
            <TouchableOpacity
              onPress={() => {
                setCurrentTask(item);
                setShareAuthorize(true);
              }}>
              <Icon name="share" width={16} height={16} />
            </TouchableOpacity>
          )}
        </View>
      );
      return {
        ...item,
      };
    });
    setDataTable(dataTable);
    setTotalItems(data.page.totalRecords);
  };
  const getMyTemplatetaskDatatableByPage = async () => {
    let payload = {
      q: '',
      listTaskId,
      parentId: 0,
      filterValue: {},
    };
    const res = await BoardServices.searchTemplateTask(
      currentPage - 1,
      pageSize,
      payload,
      'createdDate,desc',
    );
    const infoUser = await getUserInforByemail(res?.data?.[0]?.createdBy);
    const newData = res?.data?.map((item: any) => {
      item.avatar = infoUser.avatar
        ? `${String.PREFIX_IMG_BASE64}${infoUser.avatar}`
        : infoUser?.imageUrl;
      return item;
    });
    setUpDatatableFromApiData({...res, data: newData});
  };

  const getUserInforByemail = async (email: string) => {
    if (email) {
      const res = await UserService.getUser(
        {login: [email]},
        {
          page: 0,
          size: 10000,
          role: true,
        },
      );
      if (res?.data?.length) {
        return res?.data?.[0];
      }
    }
  };
  const getAuthorizedTemplateDataTableBypage = async () => {
    const resListTask = await BoardServices.getTaskById(listTaskId);
    const resAcl = await BoardServices.getGroupUserBelong(dataAccount.id || 11);
    let payload = {
      groupUserIdSharedList: resAcl.map((item: any) => item.id),
      listTaskId,
      parentId: 0,
      privateLt: resListTask.privateLt,
      q: '',
      userIdShared: dataAccount.id || 11,
    };
    const resTemplateTask = await BoardServices.searchTemplateTask(
      currentPage - 1,
      pageSize,
      payload,
      'createdDate,desc',
    );
    setUpDatatableFromApiData(resTemplateTask);
  };
  const callWhichApi = async () => {
    if (KEY_TASK['template-task'] === keyTaskSelect) {
      await getMyTemplatetaskDatatableByPage();
    } else {
      await getAuthorizedTemplateDataTableBypage();
    }
  };

  useEffect(() => {
    callWhichApi();
  }, [currentPage]);

  const handleDelete = async () => {
    try {
      await Taskservices.deleteTaskById(currentTask?.id || '');
      setModalDelete(false);
      getMyTemplatetaskDatatableByPage();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Có lỗi xảy ra',
      });
    }
  };
  const handleCopy = async () => {
    try {
      setModalCopy(false);
      await Taskservices.copyTemplateTask(currentTask?.id || '');
      getMyTemplatetaskDatatableByPage();
      Toast.show({
        type: 'success',
        text1: t('CM.noti'),
        text2: 'Copy task thành công',
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Có lỗi xảy ra',
      });
    }
  };
  return (
    <SafeAreaView edges={['bottom']} style={{flex: 1}}>
      <HeaderCM
        titleStyle={{
          fontSize: 30,
          fontFamily: Font.InterBold700,
          lineHeight: 48,
        }}
        title={listTaskName}
      />
      <TextCM
        style={{
          color: 'rgba(0, 32, 77, .9)',
          fontSize: 30,
          fontFamily: Font.InterBold700,
          lineHeight: 48,
          margin: 10,
        }}>
        {'Danh sách mẫu công việc'}
      </TextCM>
      <ScrollView style={{flex: 1}}>
        <TableCM
          stickyLeft={true}
          stickyColumnLeftIndex={1}
          tableHeaders={[
            'STT',
            'board.table-name', // Tiêu đề
            'board.table-tags', // Nhãn dán
            'board.table-createdDate', // Ngày tạo
            'board.table-createdBy', // Người tạo
            'board.table-process', // Quy trình
            'board.table-numberSubtasks', // Công việc con
            'board.table-action', //  Hành động
          ]}
          tableData={dataTable}
          useOnLayout={true}
        />
      </ScrollView>
      {totalItems > 0 && (
        <PagingCM
          collectionSize={totalItems}
          currentPage={currentPage}
          pageSize={pageSize}
          onPageChange={currentPage => setCurrentPage(currentPage)}
        />
      )}
      <ModalConfirmCM
        type="cancel"
        title={'Xoá mẫu công việc'}
        content={'Bạn có muốn xoá mẫu công việc'}
        onClose={() => setModalDelete(false)}
        isVisible={modalDelete}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleDelete()}
      />
      <ModalConfirmCM
        type="info"
        title={'Nhân bản mẫu công việc'}
        content={'Bạn có chắc chắn muốn nhân bản mẫu công việc?'}
        onClose={() => setModalCopy(false)}
        isVisible={modalCopy}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleCopy()}
      />
      <ModalFullScreen
        isVisible={shareAuthorize}
        children={
          <AuthorityAndShareScreen
            type="T"
            onClose={() => setShareAuthorize(false)}
            resource={currentTask}
          />
        }
      />
    </SafeAreaView>
  );
};
export default MyTemplateTask;
