import {
  Keyboard,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useEffect, useMemo, useState} from 'react';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Color} from '../../../../../../../constants';
import {useTaskService} from '../../../../../../../hooks/apiHooks/useAPI';
import {useAppSelector} from '../../../../../../../hooks/useRedux';
import InputCM from '../../../../../../components/TextField/InputCM';
import TextFieldCM from '../../../../../../components/TextField';
import ButtonCM from '../../../../../../components/Button';
import {IListTag, ITask} from '../../../../store/interface';
import DropDownPicker from 'react-native-dropdown-picker';
import Toast from 'react-native-toast-message';
import TextCM from '../../../../../../components/Text';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {useSafeAreaInsets} from 'react-native-safe-area-context';

type Props = {
  onClose: () => void;
  taskSelect?: ITask;
};

const CreateTemplateTask = ({onClose, taskSelect}: Props) => {
  const insets = useSafeAreaInsets();
  const TaskService = useTaskService();
  const {dataAccount} = useAppSelector(state => state.account);

  const [templateTag, setTemplateTag] = useState<string[]>([]);
  const [templateName, setTemplateName] = useState('');
  const [templateDescription, setTemplateDescription] = useState('');

  const [data, setData] = useState<IListTag[]>([]);
  const [open, setOpen] = useState(false);
  const [isDisableBtn, setIsDisableBtn] = useState(false);

  const getListTags = async () => {
    const res = (await TaskService.getListTagsByNameAndCustId(
      '',
      dataAccount.custId?.toString() || '7',
    )) as IListTag[];
    const mapNameValue: {[key: string]: number} = {};
    let filltered = res.filter(item => {
      const res = !mapNameValue[item.name];
      mapNameValue[item.name] = 1;
      return res;
    });
    setData(filltered);
  };
  const initData = () => {
    getListTags();
    setTemplateName(taskSelect?.name || '');
  };
  useEffect(() => {
    initData();
  }, []);

  const handleSaveNewTemplate = async () => {
    try {
      setIsDisableBtn(true);
      const res = await TaskService.saveTemplateListTask({
        ...(taskSelect as ITask),
        name: templateName || '',
        description: templateDescription || '',
        tags: templateTag,
      });
      if (res) {
        Toast.show({
          text1: 'Thông báo',
          text2: 'Lưu mẫu mới thành công',
          type: 'success',
        });
        onClose();
      } else {
        Toast.show({
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra khi lưu mẫu mới',
          type: 'error',
        });
      }
    } catch (error) {
      Toast.show({
        text1: 'Có lỗi xảy ra khi lưu mẫu mới',
        type: 'error',
      });
    } finally {
      setIsDisableBtn(false);
    }
  };
  return (
    <TouchableWithoutFeedback
      onPress={() => {
        Keyboard.dismiss();
        setOpen(false);
      }}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        keyboardVerticalOffset={
          Platform.OS === 'ios' ? -(insets.bottom - 100) : -30
        }
        style={{flex: 1}}>
        <KeyboardAwareScrollView style={{flex: 1, paddingHorizontal: 16}}>
          <ScrollView style={{flex: 1}}>
            <HeaderCM
              contentStyle={{backgroundColor: '#fff'}}
              title={'Thêm mới mẫu'}
              titleStyle={{color: Color.Black}}
              onPressIconLeft={() => onClose()}
              fillIconBackLeft={Color.Black}
            />

            <View style={{height: 80}}>
              <InputCM
                label={'Tên mẫu'}
                isRequired={true}
                value={templateName}
                onChangeText={setTemplateName}
              />
            </View>

            <TextCM style={{marginBottom: 5}}>Tags</TextCM>
            <View style={{zIndex: open ? 1 : 0}}>
              <DropDownPicker
                multiple={true}
                open={open}
                value={templateTag}
                setValue={setTemplateTag}
                mode="BADGE"
                badgeDotColors={[
                  '#e76f51',
                  '#00b4d8',
                  '#e9c46a',
                  '#e76f51',
                  '#8ac926',
                  '#00b4d8',
                  '#e9c46a',
                ]}
                items={data.map(org => ({
                  ...org,
                  value: org.id,
                  label: org.name,
                }))}
                setItems={setData}
                searchable
                setOpen={value => {
                  setOpen(value);
                }}
                placeholder={'Chọn tags'}
                style={{
                  borderRadius: 8,
                  borderColor: Color.borderColor,
                }}
                searchContainerStyle={{
                  borderColor: Color.borderColor,
                }}
                searchTextInputStyle={{
                  borderColor: Color.borderColor,
                }}
                dropDownContainerStyle={{
                  borderColor: Color.borderColor,
                }}
                searchPlaceholderTextColor={Color.Text}
                placeholderStyle={{
                  color: Color.Text,
                }}
              />
            </View>

            <View style={{marginTop: 10, marginBottom: 5, padding: 5}}>
              <TextCM style={{marginBottom: 5}}>{'Mô tả'}</TextCM>
              <TextFieldCM
                value={templateDescription}
                onChangeText={setTemplateDescription}
                placeholder="Nhập nội dung"
                multiline={true}
                maxLength={300}
              />
            </View>
          </ScrollView>
        </KeyboardAwareScrollView>
        <ButtonCM
          style={{
            marginHorizontal: 16,
          }}
          label={'Lưu'}
          onPress={() => handleSaveNewTemplate()}
          disabled={isDisableBtn}
        />
      </KeyboardAvoidingView>
    </TouchableWithoutFeedback>
  );
};
export default CreateTemplateTask;
